begin;

drop index if exists public.questions_question_text_unique_idx;
create unique index if not exists questions_question_text_unkeyed_unique_idx
  on public.questions (question_text) where content_key is null;

insert into public.subjects (name, slug, description, display_order) values
  ('Physics', 'physics', 'Physics questions from the first full PMA mock test.', 16)
on conflict (slug) do nothing;

insert into public.mock_tests (title, slug, description, branch_id, exam_id, duration_minutes, total_questions, difficulty, is_premium, is_active, category)
select '1st Full Mock Test', 'first-full-mock-test',
       'PMA Long Course 159 full-length paper: 200 questions across verbal and non-verbal intelligence, physics, English, and general knowledge.',
       branch.id, exam.id, 105, 200, 'MEDIUM', false, true, 'Full Mock Test'
from public.military_branches branch
join public.exams exam on exam.slug = 'pma-long-course-initial-test'
where branch.slug = 'pak-army'
on conflict (slug) do update set
  title = excluded.title, description = excluded.description, branch_id = excluded.branch_id,
  exam_id = excluded.exam_id, duration_minutes = excluded.duration_minutes, total_questions = excluded.total_questions,
  difficulty = excluded.difficulty, is_premium = excluded.is_premium, is_active = true, category = excluded.category, updated_at = now();

with first_full_mock_seed (question_number, subject_slug, category, question_text, question_type, difficulty, option_a, option_b, option_c, option_d, correct_option, explanation, image_url) as (
values
(1, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 3, 6, 12, 24, ?', 'MCQ', 'EASY', '36', '42', '48', '52', 'C', 'Each term is doubled (×2): 24 × 2 = 48.', null),
(2, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 100, 91, 82, 73, ?', 'MCQ', 'EASY', '65', '62', '66', '64', 'D', 'Each term decreases by 9: 73 − 9 = 64.', null),
(3, 'verbal-intelligence', 'Verbal Intelligence', 'Pen : Write :: Knife : ?', 'MCQ', 'EASY', 'Sharp', 'Steel', 'Kitchen', 'Cut', 'D', 'A pen is used to write; a knife is used to cut (function relationship).', null),
(4, 'verbal-intelligence', 'Verbal Intelligence', 'Doctor : Hospital :: Teacher : ?', 'MCQ', 'EASY', 'Student', 'School', 'Book', 'Chalk', 'B', 'A doctor works in a hospital; a teacher works in a school (worker : workplace).', null),
(5, 'verbal-intelligence', 'Verbal Intelligence', 'Which one is different from the rest? Apple, Mango, Banana, Potato', 'MCQ', 'EASY', 'Apple', 'Mango', 'Potato', 'Banana', 'C', 'Apple, mango and banana are fruits; potato is a vegetable.', null),
(6, 'verbal-intelligence', 'Verbal Intelligence', 'Which one is different from the rest? Karachi, Lahore, Quetta, Indus', 'MCQ', 'EASY', 'Lahore', 'Indus', 'Karachi', 'Quetta', 'B', 'Karachi, Lahore and Quetta are cities; the Indus is a river.', null),
(7, 'verbal-intelligence', 'Verbal Intelligence', 'Find the next letter: A, C, E, G, ?', 'MCQ', 'EASY', 'K', 'H', 'I', 'J', 'C', 'Alternate letters are skipped (+2 positions): G (7) → I (9).', null),
(8, 'verbal-intelligence', 'Verbal Intelligence', 'If CAT is written as DBU, how will DOG be written in the same code?', 'MCQ', 'EASY', 'EOH', 'DPH', 'CNF', 'EPH', 'D', 'Every letter is moved one step forward: D→E, O→P, G→H, so DOG = EPH.', null),
(9, 'verbal-intelligence', 'Verbal Intelligence', 'Pointing to a man, Ali said, "He is the son of my father''s only son." How is the man related to Ali?', 'MCQ', 'EASY', 'Father', 'Brother', 'Nephew', 'Son', 'D', 'Ali''s father''s only son is Ali himself. So the man is Ali''s son.', null),
(10, 'verbal-intelligence', 'Verbal Intelligence', 'Ahmed walks 5 km towards the north, then turns right and walks 5 km. In which direction is he now from his starting point?', 'MCQ', 'EASY', 'North-West', 'East', 'North-East', 'South-East', 'C', 'North 5 km and then East 5 km (right turn) puts him exactly north-east of the start.', null),
(11, 'verbal-intelligence', 'Verbal Intelligence', 'In a row of 20 students, Ali is 8th from the left. What is his position from the right end?', 'MCQ', 'EASY', '11', '13', '14', '12', 'B', 'Position from right = 20 − 8 + 1 = 13.', null),
(12, 'verbal-intelligence', 'Verbal Intelligence', 'What is 15% of 200?', 'MCQ', 'EASY', '25', '30', '20', '35', 'B', '15/100 × 200 = 30.', null),
(13, 'verbal-intelligence', 'Verbal Intelligence', 'If today is Monday, what day of the week will it be after 10 days?', 'MCQ', 'EASY', 'Tuesday', 'Friday', 'Wednesday', 'Thursday', 'D', '10 = 7 + 3, so count 3 days ahead of Monday: Thursday.', null),
(14, 'verbal-intelligence', 'Verbal Intelligence', 'Select the word opposite in meaning to ANCIENT.', 'MCQ', 'EASY', 'Old', 'Historic', 'Modern', 'Antique', 'C', 'Ancient means very old; its opposite is modern.', null),
(15, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 1, 4, 9, 16, 25, ?', 'MCQ', 'EASY', '35', '30', '49', '36', 'D', 'These are perfect squares: 1², 2², 3², 4², 5², 6² = 36.', null),
(16, 'verbal-intelligence', 'Verbal Intelligence', 'What time will it be 3 hours 45 minutes after 8:30 a.m.?', 'MCQ', 'EASY', '12:05 p.m.', '12:45 p.m.', '11:15 a.m.', '12:15 p.m.', 'D', '8:30 + 3:45 = 12:15.', null),
(17, 'verbal-intelligence', 'Verbal Intelligence', 'What is the average of 10, 20, 30 and 40?', 'MCQ', 'EASY', '20', '25', '100', '30', 'B', 'Sum = 100; 100 ÷ 4 = 25.', null),
(18, 'verbal-intelligence', 'Verbal Intelligence', 'Ahmed is taller than Bilal, and Bilal is taller than Kamran. Who is the shortest of the three?', 'MCQ', 'EASY', 'Ahmed', 'Kamran', 'Bilal', 'Cannot be determined', 'B', 'Ahmed > Bilal > Kamran, so Kamran is the shortest.', null),
(19, 'verbal-intelligence', 'Verbal Intelligence', 'Which number is different from the rest? 2, 3, 5, 9, 11', 'MCQ', 'EASY', '5', '11', '2', '9', 'D', '2, 3, 5 and 11 are prime numbers; 9 = 3 × 3 is not.', null),
(20, 'verbal-intelligence', 'Verbal Intelligence', 'Find the next pair: AB, CD, EF, GH, ?', 'MCQ', 'EASY', 'JK', 'IK', 'HI', 'IJ', 'D', 'Consecutive letters in pairs: after GH comes IJ.', null),
(21, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 2, 6, 12, 20, 30, ?', 'MCQ', 'MEDIUM', '42', '44', '40', '36', 'A', 'Differences are 4, 6, 8, 10, so the next difference is 12: 30 + 12 = 42 (terms are n × (n+1)).', null),
(22, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 1, 2, 6, 24, 120, ?', 'MCQ', 'MEDIUM', '240', '720', '840', '600', 'B', 'Multiply by 2, 3, 4, 5, then 6: 120 × 6 = 720 (factorials).', null),
(23, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 2, 3, 5, 7, 11, 13, ?', 'MCQ', 'MEDIUM', '17', '15', '19', '21', 'A', 'The series is of prime numbers; the next prime after 13 is 17.', null),
(24, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 5, 11, 23, 47, ?', 'MCQ', 'MEDIUM', '91', '95', '96', '94', 'B', 'Each term = previous × 2 + 1: 47 × 2 + 1 = 95.', null),
(25, 'verbal-intelligence', 'Verbal Intelligence', 'Find the next letter: B, E, H, K, N, ?', 'MCQ', 'MEDIUM', 'R', 'P', 'Q', 'S', 'C', 'Each letter moves 3 steps forward: N (14) + 3 = 17 = Q.', null),
(26, 'verbal-intelligence', 'Verbal Intelligence', 'Find the next pair: AZ, BY, CX, DW, ?', 'MCQ', 'MEDIUM', 'DV', 'EV', 'EU', 'FV', 'B', 'The first letter moves forward (A, B, C, D, E) and the second moves backward (Z, Y, X, W, V).', null),
(27, 'verbal-intelligence', 'Verbal Intelligence', '5 : 125 :: 6 : ?', 'MCQ', 'MEDIUM', '216', '186', '36', '196', 'A', '5³ = 125, so 6³ = 216 (number : its cube).', null),
(28, 'verbal-intelligence', 'Verbal Intelligence', 'Bird : Nest :: Bee : ?', 'MCQ', 'MEDIUM', 'Wing', 'Honey', 'Hive', 'Flower', 'C', 'A nest is the home of a bird; a hive is the home of a bee.', null),
(29, 'verbal-intelligence', 'Verbal Intelligence', 'In a certain code, TABLE is written as UBCMF. How will CHAIR be written in that code?', 'MCQ', 'MEDIUM', 'DIBJQ', 'DJCKT', 'DIBJS', 'BGZHQ', 'C', 'Every letter is moved one step forward: C→D, H→I, A→B, I→J, R→S.', null),
(30, 'verbal-intelligence', 'Verbal Intelligence', 'If A = 1, B = 2, C = 3 … Z = 26, what is the sum of the letter values of the word ARMY?', 'MCQ', 'MEDIUM', '56', '57', '55', '59', 'B', 'A(1) + R(18) + M(13) + Y(25) = 57.', null),
(31, 'verbal-intelligence', 'Verbal Intelligence', 'A is the sister of B. C is the mother of B. D is the father of C. How is A related to D?', 'MCQ', 'MEDIUM', 'Daughter', 'Niece', 'Sister', 'Granddaughter', 'D', 'A and B are children of C. D is C''s father, so D is A''s grandfather and A is his granddaughter.', null),
(32, 'verbal-intelligence', 'Verbal Intelligence', 'Pointing to a lady, Sara said, "She is the daughter of my father''s only brother." How is the lady related to Sara?', 'MCQ', 'MEDIUM', 'Cousin', 'Sister', 'Aunt', 'Niece', 'A', 'Father''s brother''s daughter is a cousin.', null),
(33, 'verbal-intelligence', 'Verbal Intelligence', 'Rashid is facing North. He turns 135° clockwise and then 90° anticlockwise. Which direction is he facing now?', 'MCQ', 'MEDIUM', 'East', 'North-West', 'North-East', 'South-East', 'C', 'Facing north (0°): +135° → 135°; −90° → 45°, which is North-East.', null),
(34, 'verbal-intelligence', 'Verbal Intelligence', 'A man walks 8 m towards the west and then 6 m towards the north. How far is he from his starting point?', 'MCQ', 'MEDIUM', '10 m', '8 m', '12 m', '14 m', 'A', 'Straight-line distance = √(8² + 6²) = √100 = 10 m.', null),
(35, 'verbal-intelligence', 'Verbal Intelligence', 'Hamza ranks 12th from the top and 25th from the bottom in a class. How many students are there in the class?', 'MCQ', 'MEDIUM', '36', '38', '37', '35', 'A', 'Total = 12 + 25 − 1 = 36.', null),
(36, 'verbal-intelligence', 'Verbal Intelligence', 'What is the angle between the hour hand and the minute hand of a clock at 3:30?', 'MCQ', 'MEDIUM', '60°', '105°', '75°', '90°', 'C', 'Hour hand at 3:30 = 105°; minute hand = 180°. Difference = 75°. (Formula: |30H − 5.5M| = |90 − 165| = 75°.)', null),
(37, 'verbal-intelligence', 'Verbal Intelligence', 'If 14 August 2026 is a Friday, what day of the week will 1 September 2026 be?', 'MCQ', 'MEDIUM', 'Wednesday', 'Tuesday', 'Monday', 'Thursday', 'B', 'From 14 Aug to 1 Sep is 18 days. 18 = 14 + 4, so 4 days after Friday is Tuesday.', null),
(38, 'verbal-intelligence', 'Verbal Intelligence', 'Statements: All soldiers are brave. Some brave persons are honest. Conclusions: I. Some soldiers are honest. II. All honest persons are soldiers.', 'MCQ', 'MEDIUM', 'Both I and II follow', 'Neither I nor II follows', 'Only II follows', 'Only I follows', 'B', 'The ''honest'' brave persons need not be soldiers, so I is not certain, and II is clearly not supported.', null),
(39, 'verbal-intelligence', 'Verbal Intelligence', 'Rs. 5,600 is divided between two persons in the ratio 3 : 4. What is the share of the person who gets the larger part?', 'MCQ', 'MEDIUM', 'Rs. 3,200', 'Rs. 2,800', 'Rs. 3,600', 'Rs. 2,400', 'A', 'Total parts = 7; one part = 5600 ÷ 7 = 800; larger share = 4 × 800 = 3,200.', null),
(40, 'verbal-intelligence', 'Verbal Intelligence', 'A car covers 180 km in 3 hours. At the same speed, how long will it take to cover 300 km?', 'MCQ', 'MEDIUM', '6 hours', '4.5 hours', '5 hours', '4 hours', 'C', 'Speed = 60 km/h; time = 300 ÷ 60 = 5 hours.', null),
(41, 'verbal-intelligence', 'Verbal Intelligence', 'A can finish a job in 12 days and B can finish it in 24 days. Working together, in how many days will they finish it?', 'MCQ', 'MEDIUM', '18 days', '6 days', '9 days', '8 days', 'D', 'Combined rate = 1/12 + 1/24 = 3/24 = 1/8 per day, so 8 days.', null),
(42, 'verbal-intelligence', 'Verbal Intelligence', 'A father is three times as old as his son. After 10 years he will be twice as old as his son. What is the present age of the son?', 'MCQ', 'MEDIUM', '8 years', '12 years', '10 years', '15 years', 'C', 'Let son = x. 3x + 10 = 2(x + 10) → x = 10.', null),
(43, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 3, 8, 15, 24, 35, ?', 'MCQ', 'HARD', '50', '48', '46', '49', 'B', 'Terms are n² − 1 for n = 2, 3, 4, 5, 6, so the next is 7² − 1 = 48.', null),
(44, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 2, 5, 10, 17, 26, ?', 'MCQ', 'HARD', '37', '38', '35', '39', 'A', 'Terms are n² + 1: 1²+1 = 2, 2²+1 = 5 … 6² + 1 = 37.', null),
(45, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 4, 6, 9, 13, 18, ?', 'MCQ', 'HARD', '22', '25', '24', '23', 'C', 'Differences are 2, 3, 4, 5, so the next difference is 6: 18 + 6 = 24.', null),
(46, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 6, 11, 21, 36, 56, ?', 'MCQ', 'HARD', '80', '81', '86', '76', 'B', 'Differences are 5, 10, 15, 20, so the next is 25: 56 + 25 = 81.', null),
(47, 'verbal-intelligence', 'Verbal Intelligence', 'Find the missing number: 2, 12, 36, 80, 150, ?', 'MCQ', 'HARD', '252', '262', '240', '210', 'A', 'Terms are n² × (n + 1): 1²×2, 2²×3, 3²×4, 4²×5, 5²×6, so the next is 6²×7 = 252.', null),
(48, 'verbal-intelligence', 'Verbal Intelligence', 'Find the next letter: Z, X, U, Q, L, ?', 'MCQ', 'HARD', 'E', 'F', 'G', 'H', 'B', 'Positions are 26, 24, 21, 17, 12 (differences −2, −3, −4, −5). Next difference −6: 12 − 6 = 6 = F.', null),
(49, 'verbal-intelligence', 'Verbal Intelligence', 'If the letters of the word MOUNTAIN are arranged in alphabetical order, which letter will be fourth from the left?', 'MCQ', 'HARD', 'M', 'O', 'N', 'T', 'C', 'A, I, M, N, N, O, T, U → the fourth letter is N.', null),
(50, 'verbal-intelligence', 'Verbal Intelligence', 'In a certain code, ARMY is written as ZINB. How will NAVY be written in that code?', 'MCQ', 'HARD', 'MZEB', 'MAEB', 'MZVB', 'OZEB', 'A', 'Each letter is replaced by its opposite letter (A↔Z, B↔Y … M↔N): N→M, A→Z, V→E, Y→B.', null),
(51, 'verbal-intelligence', 'Verbal Intelligence', 'If A + B means A is the mother of B, A − B means A is the brother of B, and A × B means A is the sister of B, which expression shows that P is the maternal uncle of Q?', 'MCQ', 'HARD', 'P + R − Q', 'P − R × Q', 'P × R + Q', 'P − R + Q', 'D', 'P − R: P is the brother of R. R + Q: R is the mother of Q. So P is Q''s mother''s brother, i.e. maternal uncle.', null),
(52, 'verbal-intelligence', 'Verbal Intelligence', 'Usman starts from point A, walks 10 m east, then 5 m south, then 6 m west and finally 5 m north. Where is he now with respect to A?', 'MCQ', 'HARD', '4 m west of A', 'At point A', '6 m east of A', '4 m east of A', 'D', 'Net east–west: 10 − 6 = 4 m east; net north–south: 5 S − 5 N = 0.', null),
(53, 'verbal-intelligence', 'Verbal Intelligence', 'Ali is 14th from the left end and Bilal is 9th from the right end of a row of boys. When they exchange places, Ali becomes 20th from the left. How many boys are in the row?', 'MCQ', 'HARD', '29', '30', '27', '28', 'D', 'Ali now stands where Bilal was: Bilal was 20th from left and 9th from right. Total = 20 + 9 − 1 = 28.', null),
(54, 'verbal-intelligence', 'Verbal Intelligence', 'At what time between 4 and 5 o''clock will the hands of a clock coincide?', 'MCQ', 'HARD', '4:21 9/11', '4:20', '4:24 6/11', '4:22 1/2', 'A', 'Minute hand gains 5.5° per minute; at 4:00 it is 120° behind. 120 ÷ 5.5 = 21 9/11 minutes after 4.', null),
(55, 'verbal-intelligence', 'Verbal Intelligence', 'Statements: All pilots are brave. No brave person is lazy. Some lazy persons are rich. Conclusions: I. No pilot is lazy. II. Some rich persons are not brave.', 'MCQ', 'HARD', 'Both I and II follow', 'Only I follows', 'Neither I nor II follows', 'Only II follows', 'A', 'Pilots ⊂ brave and brave ∩ lazy = ∅ → no pilot is lazy (I). The rich persons who are lazy cannot be brave → some rich persons are not brave (II).', null),
(56, 'verbal-intelligence', 'Verbal Intelligence', 'The price of an article is first increased by 20% and then decreased by 20%. The net change in the original price is:', 'MCQ', 'HARD', '4% decrease', '2% decrease', '4% increase', 'No change', 'A', '100 → 120 → 96. Net change = 4% decrease.', null),
(57, 'verbal-intelligence', 'Verbal Intelligence', 'A man sold an article for Rs. 1,080 at a loss of 10%. At what price should he sell it to gain 10%?', 'MCQ', 'HARD', 'Rs. 1,200', 'Rs. 1,296', 'Rs. 1,188', 'Rs. 1,320', 'D', 'CP = 1080 ÷ 0.9 = 1,200. Selling price for 10% gain = 1,200 × 1.1 = 1,320.', null),
(58, 'verbal-intelligence', 'Verbal Intelligence', 'A sum of money doubles itself in 8 years at simple interest. In how many years will it become three times?', 'MCQ', 'HARD', '20 years', '12 years', '16 years', '24 years', 'C', 'Interest equal to the principal takes 8 years; to make it triple the interest must be twice the principal: 2 × 8 = 16 years.', null),
(59, 'verbal-intelligence', 'Verbal Intelligence', 'Two trains of lengths 120 m and 180 m run on parallel tracks in opposite directions at 54 km/h and 36 km/h. How long will they take to cross each other?', 'MCQ', 'HARD', '12 seconds', '10 seconds', '15 seconds', '18 seconds', 'A', 'Relative speed = 90 km/h = 25 m/s. Distance = 300 m. Time = 300 ÷ 25 = 12 s.', null),
(60, 'verbal-intelligence', 'Verbal Intelligence', 'Pipes A and B can fill a tank in 10 hours and 15 hours respectively, and pipe C can empty it in 30 hours. If all three are opened together, how long will the tank take to fill?', 'MCQ', 'HARD', '7.5 hours', '8 hours', '9 hours', '6 hours', 'A', 'Net rate = 1/10 + 1/15 − 1/30 = 4/30 = 2/15 per hour → 7.5 hours.', null),
(61, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 1: Which figure is the odd one out?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'B', 'Three figures have 3 sides; the odd one has 4 sides.', '/images/full-mock-tests/first-full-mock-test/q061.png'),
(62, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 2: Which figure will come next in the series?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'D', 'The number of dots increases by 2 each time (1, 3, 5, 7 → 9).', '/images/full-mock-tests/first-full-mock-test/q062.png'),
(63, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 3: Which figure will come next in the series?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'A', 'The arrow turns 90° anticlockwise at every step.', '/images/full-mock-tests/first-full-mock-test/q063.png'),
(64, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 4: In every row, one rule connects the number of dots. Which figure completes the last row?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'B', 'In each row the first two figures'' dots added together give the third: 2 + 2 = 4.', '/images/full-mock-tests/first-full-mock-test/q064.png'),
(65, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 5: Which figure will come next in the series?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'C', 'The number of sides increases by 1 each time (3, 4, 5, 6 → 7).', '/images/full-mock-tests/first-full-mock-test/q065.png'),
(66, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 6: How many triangles are there in the figure?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'C', '3 line(s) from the apex give 5 points on the base line; every pair of base points with the apex makes a triangle: C(5,2) = 10.', '/images/full-mock-tests/first-full-mock-test/q066.png'),
(67, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 7: In every row, one rule connects the number of dots. Which figure completes the last row?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'D', 'In each row the first two figures'' dots added together give the third: 3 + 3 = 6.', '/images/full-mock-tests/first-full-mock-test/q067.png'),
(68, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 8: Which figure is the odd one out?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'C', 'Three figures have 3 sides; the odd one has 5 sides.', '/images/full-mock-tests/first-full-mock-test/q068.png'),
(69, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 9: Which figure will come next in the series?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'C', 'The shapes repeat in a cycle of three, while the shading alternates between unshaded and shaded at each step.', '/images/full-mock-tests/first-full-mock-test/q069.png'),
(70, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'A solid cube is painted red on all six faces and then cut into 27 equal small cubes (3 × 3 × 3). How many small cubes have exactly three faces painted?', 'NON_VERBAL', 'EASY', '1', '12', '6', '8', 'D', 'For an 3×3×3 cube: 3 faces → 8 (corners); 2 faces → 12(3−2) = 12; 1 face → 6(3−2)² = 6; no face → (3−2)³ = 1. Answer: 8.', null),
(71, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'A solid cube is painted red on all six faces and then cut into 27 equal small cubes (3 × 3 × 3). How many small cubes have exactly one face painted?', 'NON_VERBAL', 'EASY', '6', '1', '8', '12', 'A', 'For an 3×3×3 cube: 3 faces → 8 (corners); 2 faces → 12(3−2) = 12; 1 face → 6(3−2)² = 6; no face → (3−2)³ = 1. Answer: 6.', null),
(72, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 12: Which figure will come next in the series?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'C', 'The arrow turns 90° clockwise at every step.', '/images/full-mock-tests/first-full-mock-test/q072.png'),
(73, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 13: Which figure will come next in the series?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'C', 'The number of sides increases by 1 each time (3, 4, 5, 6 → 7).', '/images/full-mock-tests/first-full-mock-test/q073.png'),
(74, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 14: Which figure will come next in the series?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'C', 'The number of dots increases by 2 each time (1, 3, 5, 7 → 9).', '/images/full-mock-tests/first-full-mock-test/q074.png'),
(75, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 15: Which figure will come next in the series?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'C', 'The arrow turns 90° clockwise at every step.', '/images/full-mock-tests/first-full-mock-test/q075.png'),
(76, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 16: Which figure is the odd one out?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'A', 'Three figures are shaded; the odd one is unshaded.', '/images/full-mock-tests/first-full-mock-test/q076.png'),
(77, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 17: Which figure is the odd one out?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'A', 'Three figures are shaded; the odd one is unshaded.', '/images/full-mock-tests/first-full-mock-test/q077.png'),
(78, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 18: How many triangles are there in the figure?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'A', '4 line(s) from the apex give 6 points on the base line; every pair of base points with the apex makes a triangle: C(6,2) = 15.', '/images/full-mock-tests/first-full-mock-test/q078.png'),
(79, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 19: Which figure is the odd one out?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'C', 'Three figures have 3 sides; the odd one has 4 sides.', '/images/full-mock-tests/first-full-mock-test/q079.png'),
(80, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 20: How many triangles are there in the figure?', 'NON_VERBAL', 'EASY', 'A', 'B', 'C', 'D', 'B', '2 line(s) from the apex give 4 points on the base line; every pair of base points with the apex makes a triangle: C(4,2) = 6.', '/images/full-mock-tests/first-full-mock-test/q080.png'),
(81, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 21: The figure is a grid of 3 rows × 3 columns of equal small squares. How many squares (of all sizes) can be counted in it?', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'C', 'Count squares of every size: 9 + 4 + 1 = 14.', '/images/full-mock-tests/first-full-mock-test/q081.png'),
(82, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 22: Each row and each column contains every shape once and every shading once. Which figure completes the grid?', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'B', 'Row 3 already has two of the three shapes and two of the three shadings; the missing shape and the missing shading must complete the row (and the column).', '/images/full-mock-tests/first-full-mock-test/q082.png'),
(83, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 23: Each row and each column contains every shape once and every shading once. Which figure completes the grid?', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'B', 'Row 3 already has two of the three shapes and two of the three shadings; the missing shape and the missing shading must complete the row (and the column).', '/images/full-mock-tests/first-full-mock-test/q083.png'),
(84, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 24: Select the mirror image (the mirror is the dashed line on the right) of the given figure.', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'D', 'A mirror image on the right is a left ↔ right flip: the column nearest the mirror stays nearest the mirror.', '/images/full-mock-tests/first-full-mock-test/q084.png'),
(85, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 25: Select the mirror image (the mirror is the dashed line on the right) of the given figure.', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'D', 'A mirror image on the right is a left ↔ right flip: the column nearest the mirror stays nearest the mirror.', '/images/full-mock-tests/first-full-mock-test/q085.png'),
(86, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 26: A square sheet of paper is folded once in half down the middle (left half folded over the right half). A hole is punched in the folded paper as shown. Which figure shows the paper when it is unfolded?', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'B', 'Unfolding reflects the hole across the fold line (vertical centre line): one hole becomes two holes at the same height, one on each side of the fold.', '/images/full-mock-tests/first-full-mock-test/q086.png'),
(87, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 27: The figure is a grid of 2 rows × 2 columns of equal small squares. How many rectangles of all sizes (including squares) are there in it?', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'D', 'Choose 2 of 3 horizontal lines and 2 of 3 vertical lines: C(3,2) × C(3,2) = 3 × 3 = 9.', '/images/full-mock-tests/first-full-mock-test/q087.png'),
(88, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 28: Three of the figures are the same shape turned to different positions. Which figure is the odd one out (a mirror image of the others)?', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'D', 'Three figures can be matched by simple rotation. The odd one is a flipped (mirror) version and can never be obtained by rotating the others.', '/images/full-mock-tests/first-full-mock-test/q088.png'),
(89, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 29: The figure is a grid of 2 rows × 3 columns of equal small squares. How many rectangles of all sizes (including squares) are there in it?', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'C', 'Choose 2 of 3 horizontal lines and 2 of 4 vertical lines: C(3,2) × C(4,2) = 3 × 6 = 18.', '/images/full-mock-tests/first-full-mock-test/q089.png'),
(90, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 30: The figure is a grid of 2 rows × 2 columns of equal small squares. How many squares (of all sizes) can be counted in it?', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'B', 'Count squares of every size: 4 + 1 = 5.', '/images/full-mock-tests/first-full-mock-test/q090.png'),
(91, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 31: Which figure will come next in the series?', 'NON_VERBAL', 'MEDIUM', 'A', 'B', 'C', 'D', 'A', 'The arrow turns 135° clockwise at every step.', '/images/full-mock-tests/first-full-mock-test/q091.png'),
