(109, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 49: Which figure will come next in the series?', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'C', 'Two changes happen together at every step: the figure turns 90° clockwise and its shading is reversed (black ↔ white).', '/images/full-mock-tests/first-full-mock-test/q109.png'),
(110, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 50: A square sheet is folded in half vertically (left over right) and then in half horizontally (bottom over top), so the folded paper is one quarter of the original. One hole is punched in the folded paper as shown. Which figure shows the paper when it is fully unfolded?', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'C', 'Each of the two folds doubles the holes: the hole is reflected across the vertical centre line and across the horizontal centre line, giving four holes at the corners of a rectangle.', '/images/full-mock-tests/first-full-mock-test/q110.png'),
(111, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 51: Two squares are shaded in each figure. Which figure will come next in the series?', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'A', 'One shaded square moves 1 step clockwise and the other moves 1 step anticlockwise around the outer ring each time.', '/images/full-mock-tests/first-full-mock-test/q111.png'),
(112, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 52: Which figure will come next in the series?', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'A', 'Two changes happen together at every step: the figure turns 90° clockwise and its shading is reversed (black ↔ white).', '/images/full-mock-tests/first-full-mock-test/q112.png'),
(113, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 53: Figure A is changed into Figure B by a rule. Apply the same rule to Figure C. (First figure : second figure :: third figure : ?)', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'C', 'The first figure is rotated 90° clockwise and shading reversed to give the second. The same change applied to the third figure gives the answer.', '/images/full-mock-tests/first-full-mock-test/q113.png'),
(114, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 54: Select the water image (the reflection in the water below the figure) of the given figure.', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'C', 'A water image is turned upside-down (top ↔ bottom) while left and right stay as they are.', '/images/full-mock-tests/first-full-mock-test/q114.png'),
(115, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 55: Figure A is changed into Figure B by a rule. Apply the same rule to Figure C. (First figure : second figure :: third figure : ?)', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'A', 'The first figure is rotated 90° anticlockwise to give the second. The same change applied to the third figure gives the answer.', '/images/full-mock-tests/first-full-mock-test/q115.png'),
(116, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 56: Figure A is changed into Figure B by a rule. Apply the same rule to Figure C. (First figure : second figure :: third figure : ?)', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'A', 'The first figure is flipped left ↔ right to give the second. The same change applied to the third figure gives the answer.', '/images/full-mock-tests/first-full-mock-test/q116.png'),
(117, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 57: A square sheet is folded in half vertically (left over right) and then in half horizontally (bottom over top), so the folded paper is one quarter of the original. One hole is punched in the folded paper as shown. Which figure shows the paper when it is fully unfolded?', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'D', 'Each of the two folds doubles the holes: the hole is reflected across the vertical centre line and across the horizontal centre line, giving four holes at the corners of a rectangle.', '/images/full-mock-tests/first-full-mock-test/q117.png'),
(118, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 58: Two squares are shaded in each figure. Which figure will come next in the series?', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'A', 'One shaded square moves 1 step clockwise and the other moves 1 step anticlockwise around the outer ring each time.', '/images/full-mock-tests/first-full-mock-test/q118.png'),
(119, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 59: A square sheet is folded in half vertically (left over right) and then in half horizontally (bottom over top), so the folded paper is one quarter of the original. One hole is punched in the folded paper as shown. Which figure shows the paper when it is fully unfolded?', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'B', 'Each of the two folds doubles the holes: the hole is reflected across the vertical centre line and across the horizontal centre line, giving four holes at the corners of a rectangle.', '/images/full-mock-tests/first-full-mock-test/q119.png'),
(120, 'non-verbal-intelligence', 'Non-Verbal Intelligence', 'Non-verbal question 60: Which figure will come next in the series?', 'NON_VERBAL', 'HARD', 'A', 'B', 'C', 'D', 'A', 'Two changes happen together at every step: the figure turns 90° clockwise and its shading is reversed (black ↔ white).', '/images/full-mock-tests/first-full-mock-test/q120.png'),
(121, 'physics', 'Physics', 'The dimensions of force are:', 'MCQ', 'EASY', '[ML²T⁻²]', '[ML⁻¹T⁻²]', '[MLT⁻¹]', '[MLT⁻²]', 'D', 'F = ma = kg · m/s² → [M][L][T⁻²].', null),
(122, 'physics', 'Physics', 'Which of the following is a vector quantity?', 'MCQ', 'EASY', 'Mass', 'Distance', 'Displacement', 'Speed', 'C', 'Displacement has both magnitude and direction; distance, speed and mass are scalars.', null),
(123, 'physics', 'Physics', 'The time period of a simple pendulum of length 2.45 m at a place where g = 9.8 m s⁻² is:', 'MCQ', 'EASY', '6.28 s', '3.14 s', '1.57 s', '9.86 s', 'B', 'T = 2π√(l/g) = 2π√(2.45/9.8) = 2π(0.5) = π ≈ 3.14 s.', null),
(124, 'physics', 'Physics', 'What force is required to produce an acceleration of 4 m s⁻² in a body of mass 5 kg?', 'MCQ', 'EASY', '9 N', '40 N', '1.25 N', '20 N', 'D', 'F = ma = 5 × 4 = 20 N.', null),
(125, 'physics', 'Physics', 'The kinetic energy of a 2 kg body moving with a speed of 3 m s⁻¹ is:', 'MCQ', 'EASY', '9 J', '12 J', '18 J', '6 J', 'A', 'K.E. = ½mv² = ½ × 2 × 9 = 9 J.', null),
(126, 'physics', 'Physics', 'How much work is done in lifting a 10 kg mass through a height of 5 m? (g = 9.8 m s⁻²)', 'MCQ', 'EASY', '245 J', '490 J', '50 J', '98 J', 'B', 'W = mgh = 10 × 9.8 × 5 = 490 J.', null),
(127, 'physics', 'Physics', 'A wave has a time period of 0.02 s. Its frequency is:', 'MCQ', 'EASY', '50 Hz', '200 Hz', '0.02 Hz', '20 Hz', 'A', 'f = 1/T = 1/0.02 = 50 Hz.', null),
(128, 'physics', 'Physics', 'A current of how much will flow through a 4 Ω resistor connected across a 12 V battery?', 'MCQ', 'EASY', '0.33 A', '48 A', '8 A', '3 A', 'D', 'I = V/R = 12/4 = 3 A (Ohm''s law).', null),
(129, 'physics', 'Physics', 'Two resistors of 6 Ω and 3 Ω are connected in parallel. Their equivalent resistance is:', 'MCQ', 'EASY', '9 Ω', '18 Ω', '2 Ω', '4.5 Ω', 'C', '1/R = 1/6 + 1/3 = 3/6 → R = 2 Ω.', null),
(130, 'physics', 'Physics', 'The output of a NOR gate is 1 (HIGH) only when:', 'MCQ', 'EASY', 'Both inputs are 0', 'Both inputs are 1', 'Any one input is 1', 'Inputs are different', 'A', 'NOR = NOT(OR). OR is 0 only when both inputs are 0, so NOR is 1 only then.', null),
(131, 'physics', 'Physics', 'A ball is thrown at 19.6 m s⁻¹ at an angle of 45° to the horizontal. Its horizontal range is (g = 9.8 m s⁻²):', 'MCQ', 'MEDIUM', '39.2 m', '19.6 m', '78.4 m', '27.7 m', 'A', 'R = v² sin 2θ / g = (19.6)² × 1 / 9.8 = 39.2 m (maximum range at 45°).', null),
(132, 'physics', 'Physics', 'A 2 kg body moving at 6 m s⁻¹ collides with a 4 kg body at rest and they stick together. Their common velocity is:', 'MCQ', 'MEDIUM', '2 m s⁻¹', '3 m s⁻¹', '1.5 m s⁻¹', '4 m s⁻¹', 'A', 'Momentum conservation: 2 × 6 = (2 + 4)v → v = 2 m s⁻¹.', null),
(133, 'physics', 'Physics', 'A 0.5 kg stone is whirled in a horizontal circle of radius 0.4 m with a speed of 4 m s⁻¹. The centripetal force on it is:', 'MCQ', 'MEDIUM', '20 N', '32 N', '5 N', '8 N', 'A', 'F = mv²/r = 0.5 × 16 / 0.4 = 20 N.', null),
(134, 'physics', 'Physics', 'The escape velocity from the surface of the earth is approximately:', 'MCQ', 'MEDIUM', '7.9 km s⁻¹', '9.8 km s⁻¹', '11.2 km s⁻¹', '15.0 km s⁻¹', 'C', 'v_esc = √(2gR) ≈ 11.2 km/s (7.9 km/s is the orbital velocity near the surface).', null),
(135, 'physics', 'Physics', 'Water flows at 2 m s⁻¹ through a pipe of diameter 4 cm which narrows to a diameter of 2 cm. The speed in the narrow part is:', 'MCQ', 'MEDIUM', '16 m s⁻¹', '4 m s⁻¹', '8 m s⁻¹', '6 m s⁻¹', 'C', 'Equation of continuity: A₁v₁ = A₂v₂. Area ∝ d², so area ratio = 4 and v₂ = 4 × 2 = 8 m/s.', null),
(136, 'physics', 'Physics', 'A 2 kg mass attached to a spring of force constant 200 N m⁻¹ executes simple harmonic motion. Its time period is:', 'MCQ', 'MEDIUM', '0.31 s', '0.63 s', '6.28 s', '1.57 s', 'B', 'T = 2π√(m/k) = 2π√(2/200) = 2π × 0.1 = 0.628 s ≈ 0.63 s.', null),
(137, 'physics', 'Physics', 'A gas at 27 °C is heated at constant pressure until its volume doubles. The final temperature is:', 'MCQ', 'MEDIUM', '54 °C', '300 °C', '600 °C', '327 °C', 'D', 'Charles'' law: V/T = constant. T₂ = 2 × 300 K = 600 K = 327 °C.', null),
(138, 'physics', 'Physics', 'The efficiency of a Carnot engine working between 600 K and 300 K is:', 'MCQ', 'MEDIUM', '50%', '25%', '75%', '100%', 'A', 'η = 1 − T₂/T₁ = 1 − 300/600 = 0.5 = 50%.', null),
(139, 'physics', 'Physics', 'Two point charges of 1 μC each are placed 0.3 m apart in air. The force between them is (k = 9 × 10⁹ N m² C⁻²):', 'MCQ', 'MEDIUM', '0.03 N', '9 N', '0.1 N', '1 N', 'C', 'F = kq₁q₂/r² = 9×10⁹ × 10⁻¹² / 0.09 = 0.1 N (repulsive).', null),
(140, 'physics', 'Physics', 'The energy stored in a 10 μF capacitor charged to 100 V is:', 'MCQ', 'MEDIUM', '0.5 J', '0.005 J', '1.0 J', '0.05 J', 'D', 'U = ½CV² = ½ × 10×10⁻⁶ × 10⁴ = 0.05 J.', null),
(141, 'physics', 'Physics', 'The power dissipated in a 5 Ω resistor carrying a current of 2 A is:', 'MCQ', 'MEDIUM', '20 W', '50 W', '10 W', '2.5 W', 'A', 'P = I²R = 4 × 5 = 20 W.', null),
(142, 'physics', 'Physics', 'A straight conductor 0.5 m long carries 4 A and is placed perpendicular to a magnetic field of 0.5 T. The force on it is:', 'MCQ', 'MEDIUM', '4 N', '1 N', '0.25 N', '2 N', 'B', 'F = BIL sin θ = 0.5 × 4 × 0.5 × 1 = 1 N.', null),
(143, 'physics', 'Physics', 'A transformer has 200 turns in the primary and 1000 turns in the secondary. If the primary is connected to 220 V a.c., the secondary voltage is:', 'MCQ', 'HARD', '44 V', '1100 V', '220 V', '4400 V', 'B', 'V_s/V_p = N_s/N_p → V_s = 220 × 1000/200 = 1100 V (step-up).', null),
(144, 'physics', 'Physics', 'The peak value of an alternating voltage is 311 V. Its r.m.s. value is approximately:', 'MCQ', 'HARD', '311 V', '220 V', '156 V', '440 V', 'B', 'V_rms = V₀/√2 = 311/1.414 ≈ 220 V.', null),
(145, 'physics', 'Physics', 'Light of photon energy 5 eV falls on a metal of work function 2 eV. The maximum kinetic energy of the emitted photoelectrons is:', 'MCQ', 'HARD', '7 eV', '2.5 eV', '2 eV', '3 eV', 'D', 'Einstein''s equation: K.E.max = hf − φ = 5 − 2 = 3 eV.', null),
(146, 'physics', 'Physics', 'The energy of a photon of wavelength 500 nm is approximately (hc = 1240 eV·nm):', 'MCQ', 'HARD', '6.20 eV', '1.24 eV', '2.48 eV', '3.10 eV', 'C', 'E = hc/λ = 1240 / 500 = 2.48 eV.', null),
(147, 'physics', 'Physics', 'In the hydrogen atom, the energy of the photon emitted when an electron jumps from the third orbit (n = 3) to the second orbit (n = 2) is:', 'MCQ', 'HARD', '10.2 eV', '3.40 eV', '1.89 eV', '12.1 eV', 'C', 'ΔE = 13.6 (1/2² − 1/3²) = 13.6 × 5/36 = 1.89 eV (first line of the Balmer series).', null),
(148, 'physics', 'Physics', 'A radioactive substance has a half-life of 4 days. The fraction of the original amount left after 12 days is:', 'MCQ', 'HARD', '1/4', '1/8', '1/3', '1/6', 'B', '12 days = 3 half-lives → (1/2)³ = 1/8.', null),
(149, 'physics', 'Physics', 'In Young''s double-slit experiment, light of wavelength 600 nm is used, the slit separation is 0.4 mm and the screen is 2 m away. The fringe spacing is:', 'MCQ', 'HARD', '6 mm', '3 mm', '0.3 mm', '1.2 mm', 'B', 'Δy = λL/d = (600×10⁻⁹ × 2)/(0.4×10⁻³) = 3×10⁻³ m = 3 mm.', null),
(150, 'physics', 'Physics', 'The mass defect of a nucleus is 0.002 u. The binding energy is approximately (1 u = 931.5 MeV):', 'MCQ', 'HARD', '18.6 MeV', '186 MeV', '0.93 MeV', '1.86 MeV', 'D', 'E = Δm × 931.5 = 0.002 × 931.5 = 1.863 MeV.', null),
(151, 'english', 'English', 'Choose the word closest in meaning to ABUNDANT.', 'MCQ', 'EASY', 'Rare', 'Scarce', 'Plentiful', 'Limited', 'C', 'Abundant means existing in large quantities — plentiful.', null),
(152, 'english', 'English', 'Choose the word opposite in meaning to BRAVE.', 'MCQ', 'EASY', 'Fearless', 'Cowardly', 'Heroic', 'Bold', 'B', 'Brave means courageous; cowardly is the opposite.', null),
(153, 'english', 'English', 'Choose the correct option: She ______ to school every day.', 'MCQ', 'EASY', 'gone', 'goes', 'go', 'going', 'B', 'A singular third-person subject takes the present-tense verb with -s/-es: goes.', null),
(154, 'english', 'English', 'Choose the correct option: Neither of the boys ______ present.', 'MCQ', 'EASY', 'were', 'have been', 'was', 'are', 'C', '''Neither'' is singular and takes a singular verb: was.', null),
(155, 'english', 'English', 'Choose the correct preposition: He is very good ______ mathematics.', 'MCQ', 'EASY', 'in', 'on', 'at', 'with', 'C', 'The correct collocation is ''good at'' a subject.', null),
(156, 'english', 'English', 'Select the correctly spelled word.', 'MCQ', 'EASY', 'Neccessary', 'Necessary', 'Necesary', 'Necessarry', 'B', 'Necessary has one c and two s''s.', null),
(157, 'english', 'English', 'One word for: a person who loves mankind and helps others.', 'MCQ', 'EASY', 'Misanthrope', 'Philanthropist', 'Pessimist', 'Egoist', 'B', 'A philanthropist works for the welfare of humanity; a misanthrope hates people.', null),
(158, 'english', 'English', 'What does the idiom "to beat about the bush" mean?', 'MCQ', 'EASY', 'To work very hard', 'To hit someone hard', 'To avoid coming to the point directly', 'To hunt animals', 'C', 'Beating about the bush means talking around a topic without getting to the point.', null),
(159, 'english', 'English', 'Choose the correct article: He is ______ honest man.', 'MCQ', 'EASY', 'the', 'no article is needed', 'an', 'a', 'C', '''Honest'' begins with a vowel sound (silent h), so ''an'' is used.', null),
(160, 'english', 'English', 'What is the plural of "phenomenon"?', 'MCQ', 'EASY', 'Phenomena', 'Phenomenes', 'Phenomenas', 'Phenomenons', 'A', 'Phenomenon is of Greek origin; its plural is phenomena.', null),
(161, 'english', 'English', 'Choose the word closest in meaning to CANDID.', 'MCQ', 'MEDIUM', 'Cunning', 'Frank', 'Sweet', 'Secretive', 'B', 'Candid means open and honest — frank.', null),
(162, 'english', 'English', 'Choose the word opposite in meaning to BENEVOLENT.', 'MCQ', 'MEDIUM', 'Malevolent', 'Generous', 'Charitable', 'Kind', 'A', 'Benevolent means well-meaning and kind; malevolent means wishing harm.', null),
(163, 'english', 'English', 'One word for: government by a small group of people.', 'MCQ', 'MEDIUM', 'Democracy', 'Monarchy', 'Anarchy', 'Oligarchy', 'D', 'Oligarchy = rule by a few; monarchy = rule by one; anarchy = no government.', null),
(164, 'english', 'English', 'What does the idiom "a blessing in disguise" mean?', 'MCQ', 'MEDIUM', 'A hidden gift', 'Something that seems bad but turns out to be good', 'A disguised person', 'A secret prayer', 'B', 'It is an apparent misfortune that eventually brings benefit.', null),
(165, 'english', 'English', 'Change into passive voice: "The teacher punished the boy."', 'MCQ', 'MEDIUM', 'The boy is punished by the teacher.', 'The boy has been punished by the teacher.', 'The teacher was punished by the boy.', 'The boy was punished by the teacher.', 'D', 'Simple past active → was/were + past participle in the passive.', null),
(166, 'english', 'English', 'Change into indirect speech: He said, "I am happy."', 'MCQ', 'MEDIUM', 'He said that he is happy.', 'He said that he was happy.', 'He said that I was happy.', 'He said that he has been happy.', 'B', 'In reported speech the present tense changes to past (am → was) and ''I'' becomes ''he''.', null),
(167, 'english', 'English', 'Choose the correct option: By the time we reached the station, the train ______.', 'MCQ', 'MEDIUM', 'had left', 'left', 'has left', 'was leaving', 'A', 'Past perfect (had left) shows the earlier of two past actions.', null),
(168, 'english', 'English', 'Choose the correct sentence.', 'MCQ', 'MEDIUM', 'He didn''t liked tea.', 'He don''t like tea.', 'He not like tea.', 'He doesn''t like tea.', 'D', 'A third-person singular subject takes ''doesn''t'' with the base verb.', null),
(169, 'english', 'English', 'Choose the correct preposition: She is married ______ a doctor.', 'MCQ', 'MEDIUM', 'to', 'from', 'with', 'by', 'A', 'The correct collocation is ''married to''.', null),
(170, 'english', 'English', 'Choose the correct option: If I ______ you, I would accept the offer.', 'MCQ', 'MEDIUM', 'were', 'was', 'am', 'will be', 'A', 'Second conditional (unreal present) uses ''were'' for all persons.', null),
(171, 'english', 'English', 'Choose the word closest in meaning to OBSOLETE.', 'MCQ', 'MEDIUM', 'Necessary', 'Modern', 'Outdated', 'Fragile', 'C', 'Obsolete means no longer in use — outdated.', null),
(172, 'english', 'English', 'Select the correctly spelled word.', 'MCQ', 'MEDIUM', 'Accommodation', 'Accomodation', 'Acommodation', 'Acomodation', 'A', 'Accommodation has double c and double m.', null),
(173, 'english', 'English', 'Choose the word closest in meaning to EPHEMERAL.', 'MCQ', 'HARD', 'Short-lived', 'Eternal', 'Fragrant', 'Heavenly', 'A', 'Ephemeral means lasting for a very short time.', null),
(174, 'english', 'English', 'Choose the word opposite in meaning to VERBOSE.', 'MCQ', 'HARD', 'Fluent', 'Wordy', 'Talkative', 'Concise', 'D', 'Verbose means using too many words; concise means brief and to the point.', null),
(175, 'english', 'English', 'One word for: one who is present everywhere.', 'MCQ', 'HARD', 'Omnivorous', 'Omnipotent', 'Omniscient', 'Omnipresent', 'D', 'Omnipresent = present everywhere; omniscient = all-knowing; omnipotent = all-powerful.', null),
(176, 'english', 'English', 'What does the idiom "to bell the cat" mean?', 'MCQ', 'HARD', 'To punish a cat', 'To make a lot of noise', 'To tell a secret', 'To take on a risky task for the common good', 'D', 'From the fable of the mice: to undertake a dangerous task on behalf of a group.', null),
(177, 'english', 'English', 'Choose the correct sentence.', 'MCQ', 'HARD', 'Hardly had he reached the station when the train left.', 'Hardly did he reached the station when the train left.', 'Hardly he had reached the station when the train left.', 'Hardly had he reached the station than the train left.', 'A', '''Hardly … when'' is the correct pair, with inversion (had he reached) after ''hardly''.', null),
(178, 'english', 'English', 'Choose the correct preposition: He insisted ______ paying the bill.', 'MCQ', 'HARD', 'to', 'on', 'for', 'at', 'B', 'The correct collocation is ''insist on''.', null),
(179, 'english', 'English', 'Choose the correct option: Each of the students ______ given a certificate.', 'MCQ', 'HARD', 'have been', 'are', 'was', 'were', 'C', '''Each'' is singular, so it takes the singular verb ''was''.', null),
(180, 'english', 'English', 'Choose the correct word: The new policy will ______ everyone in the country.', 'MCQ', 'HARD', 'effect', 'effects', 'afect', 'affect', 'D', '''Affect'' is the verb meaning to influence; ''effect'' is usually the noun (result).', null),
(181, 'general-knowledge', 'General Knowledge', 'The Pakistan (Lahore) Resolution was passed on:', 'MCQ', 'EASY', '6 December 1945', '23 March 1940', '30 December 1906', '14 August 1947', 'B', 'The Lahore Resolution was adopted at the Muslim League session at Minto Park, Lahore, on 23 March 1940.', null),
(182, 'general-knowledge', 'General Knowledge', 'Who was the first Governor-General of Pakistan?', 'MCQ', 'EASY', 'Khawaja Nazimuddin', 'Ghulam Muhammad', 'Liaquat Ali Khan', 'Quaid-e-Azam Muhammad Ali Jinnah', 'D', 'Jinnah took oath as the first Governor-General on 15 August 1947.', null),
(183, 'general-knowledge', 'General Knowledge', 'The highest mountain peak in Pakistan is:', 'MCQ', 'EASY', 'Nanga Parbat', 'Broad Peak', 'K2', 'Tirich Mir', 'C', 'K2 (Godwin-Austen) in the Karakoram is the highest peak in Pakistan and second highest in the world.', null),
(184, 'general-knowledge', 'General Knowledge', 'The longest river of Pakistan is:', 'MCQ', 'EASY', 'Sutlej', 'Jhelum', 'Indus', 'Chenab', 'C', 'The Indus (about 3,000 km) is the longest river in Pakistan.', null),
(185, 'general-knowledge', 'General Knowledge', 'The Khyber Pass connects Pakistan with:', 'MCQ', 'EASY', 'India', 'Afghanistan', 'China', 'Iran', 'B', 'The Khyber Pass links Peshawar (Pakistan) with Jalalabad/Kabul side of Afghanistan.', null),
(186, 'general-knowledge', 'General Knowledge', 'The Pakistan Military Academy (PMA) is located at:', 'MCQ', 'EASY', 'Quetta', 'Kohat', 'Kakul, Abbottabad', 'Rawalpindi', 'C', 'PMA Kakul is in Abbottabad, Khyber Pakhtunkhwa.', null),
(187, 'general-knowledge', 'General Knowledge', 'Who was the first Prime Minister of Pakistan?', 'MCQ', 'EASY', 'Liaquat Ali Khan', 'Feroz Khan Noon', 'H. S. Suhrawardy', 'Chaudhry Muhammad Ali', 'A', 'Liaquat Ali Khan served from 1947 until his assassination in 1951.', null),
(188, 'general-knowledge', 'General Knowledge', 'Allama Iqbal presented the idea of a separate Muslim state in North-West India in his presidential address at Allahabad in:', 'MCQ', 'MEDIUM', '1920', '1937', '1940', '1930', 'D', 'The Allahabad Address was delivered at the Muslim League session in December 1930.', null),
(189, 'general-knowledge', 'General Knowledge', 'Tarbela Dam is built on the river:', 'MCQ', 'MEDIUM', 'Indus', 'Kabul', 'Jhelum', 'Chenab', 'A', 'Tarbela, the largest earth-filled dam in the world, is on the Indus in Khyber Pakhtunkhwa.', null),
(190, 'general-knowledge', 'General Knowledge', 'Who was the first recipient of the Nishan-e-Haider?', 'MCQ', 'MEDIUM', 'Captain Raja Muhammad Sarwar Shaheed', 'Major Tufail Muhammad Shaheed', 'Havaldar Lalak Jan Shaheed', 'Major Aziz Bhatti Shaheed', 'A', 'Captain Raja Muhammad Sarwar (1948 Kashmir operations) was the first recipient of Pakistan''s highest gallantry award.', null),
(191, 'general-knowledge', 'General Knowledge', 'The motto of the Pakistan Army is:', 'MCQ', 'MEDIUM', 'Unity, Faith, Discipline', 'Faith, Unity, Sacrifice', 'Iman, Taqwa, Jihad fi Sabilillah', 'Duty, Honour, Country', 'C', 'The Army motto is ''Iman, Taqwa, Jihad fi Sabilillah'' (Faith, Piety, Striving in the Way of Allah).', null),
(192, 'general-knowledge', 'General Knowledge', 'The United Nations Organization was founded in:', 'MCQ', 'MEDIUM', '1945', '1950', '1948', '1919', 'A', 'The UN came into existence on 24 October 1945 after the Second World War.', null),
(193, 'general-knowledge', 'General Knowledge', 'Which is the largest country of the world by area?', 'MCQ', 'MEDIUM', 'United States', 'Russia', 'China', 'Canada', 'B', 'Russia is the largest country by area.', null),
