(195, 'general-knowledge', 'General Knowledge', 'Pakistan conducted its nuclear tests at Chagai on:', 'MCQ', 'HARD', '28 May 1999', '11 May 1998', '28 May 1998', '14 August 1998', 'C', 'Pakistan carried out its tests on 28 May 1998, observed as Youm-e-Takbeer.', null),
(196, 'general-knowledge', 'General Knowledge', 'Pakistan''s first Constitution was enforced in:', 'MCQ', 'HARD', '1947', '1973', '1962', '1956', 'D', 'The first Constitution was enforced on 23 March 1956; the 1962 and 1973 Constitutions followed.', null),
(197, 'general-knowledge', 'General Knowledge', 'The Battle of Badr was fought in the year:', 'MCQ', 'HARD', '2 A.H.', '1 A.H.', '3 A.H.', '5 A.H.', 'A', 'Badr was fought on 17 Ramadan, 2 A.H. (624 CE); Uhud 3 A.H.; Khandaq 5 A.H.', null),
(198, 'general-knowledge', 'General Knowledge', 'Which Nishan-e-Haider recipient belonged to the Pakistan Air Force?', 'MCQ', 'HARD', 'Major Muhammad Akram Shaheed', 'Major Shabbir Sharif Shaheed', 'Captain Karnal Sher Khan Shaheed', 'Pilot Officer Rashid Minhas Shaheed', 'D', 'Pilot Officer Rashid Minhas (1971) is the PAF''s Nishan-e-Haider recipient; the others served in the Army.', null),
(199, 'general-knowledge', 'General Knowledge', 'The South Asian Association for Regional Cooperation (SAARC) was founded in:', 'MCQ', 'HARD', '1980', '1985', '1992', '1971', 'B', 'SAARC was established at a Dhaka summit in December 1985.', null),
(200, 'general-knowledge', 'General Knowledge', 'Who moved the Lahore (Pakistan) Resolution in 1940?', 'MCQ', 'HARD', 'Allama Iqbal', 'Sir Syed Ahmad Khan', 'Chaudhry Rahmat Ali', 'A. K. Fazlul Haq', 'D', 'The resolution was moved by A. K. Fazlul Haq (Bengal) and seconded by Chaudhry Khaliquzzaman. End of mock test. Best of luck for PMA Long Course 159.', null)
),
question_upserts as (
  insert into public.questions (subject_id, question_text, question_type, difficulty, option_a, option_b, option_c, option_d, correct_option, explanation, image_url, source, is_verified, is_active, content_key, category, priority, source_type, source_reference)
  select subject.id, seed.question_text, seed.question_type, seed.difficulty, seed.option_a, seed.option_b, seed.option_c, seed.option_d, seed.correct_option, seed.explanation, seed.image_url,
         '1st full Mock Test project PDF', false, true, 'first-full-mock-test-q' || lpad(seed.question_number::text, 3, '0'), seed.category, 'MEDIUM', 'PREPARATION_PATTERN', 'Source: Full mock tests/1st full Mock Test.pdf'
  from first_full_mock_seed seed join public.subjects subject on subject.slug = seed.subject_slug
  on conflict (content_key) where content_key is not null do update set
    subject_id = excluded.subject_id, question_text = excluded.question_text, question_type = excluded.question_type, difficulty = excluded.difficulty,
    option_a = excluded.option_a, option_b = excluded.option_b, option_c = excluded.option_c, option_d = excluded.option_d, correct_option = excluded.correct_option,
    explanation = excluded.explanation, image_url = excluded.image_url, is_active = true, category = excluded.category, priority = excluded.priority, source_type = excluded.source_type, source_reference = excluded.source_reference, updated_at = now()
  returning id, content_key
)
select count(*) from question_upserts;

delete from public.mock_test_questions link using public.mock_tests test where link.mock_test_id = test.id and test.slug = 'first-full-mock-test';

insert into public.mock_test_questions (mock_test_id, question_id, question_number)
select test.id, question.id, numbered.question_number
from generate_series(1, 200) as numbered(question_number)
join public.questions question on question.content_key = 'first-full-mock-test-q' || lpad(numbered.question_number::text, 3, '0')
join public.mock_tests test on test.slug = 'first-full-mock-test'
order by numbered.question_number;

do $$
declare v_mock_id uuid;
begin
  select id into v_mock_id from public.mock_tests where slug = 'first-full-mock-test' and is_active and total_questions = 200;
  if v_mock_id is null or (select count(*) from public.mock_test_questions where mock_test_id = v_mock_id) <> 200 then
    raise exception 'The first full mock test must have exactly 200 linked questions';
  end if;
  if (select count(*) from public.mock_test_questions where mock_test_id = v_mock_id and question_number between 61 and 120 and question_id in (select id from public.questions where image_url is not null)) <> 58 then
    raise exception 'The non-verbal figure crops do not match the source paper';
  end if;
  if exists (select 1 from public.mock_test_questions link join public.questions question on question.id = link.question_id where link.mock_test_id = v_mock_id and (question.correct_option not in ('A', 'B', 'C', 'D') or question.option_a is null or question.option_b is null or question.option_c is null or question.option_d is null)) then
    raise exception 'Every full mock question must have four options and a correct answer';
  end if;
end $$;

commit;
